create table if not exists public.notification_preferences (user_id uuid primary key references auth.users(id) on delete cascade, enabled boolean not null default true, location_alerts boolean not null default true, nearby_updates boolean not null default true, verification_updates boolean not null default true, community_updates boolean not null default true, business_updates boolean not null default true, fleet_updates boolean not null default true, quiet_hours_start time, quiet_hours_end time, updated_at timestamptz not null default now()); create table if not exists public.notification_events (id uuid primary key default gen_random_uuid(), event_type text not null, actor_user_id uuid references auth.users(id) on delete set null, location_id uuid references public.locations(id) on delete cascade, audience_scope text not null default 'nearby' check (audience_scope in ('user','nearby','followers','business','fleet','enterprise','admin')), payload jsonb not null default '{}'::jsonb, dedupe_key text, created_at timestamptz not null default now(), expires_at timestamptz); create unique index if not exists uq_notification_events_dedupe on public.notification_events(dedupe_key) where dedupe_key is not null; create index if not exists idx_notification_events_location_time on public.notification_events(location_id,created_at desc); create index if not exists idx_notification_events_scope_time on public.notification_events(audience_scope,created_at desc); alter table public.notification_preferences enable row level security; alter table public.notification_events enable row level security; create policy notification_preferences_own on public.notification_preferences for all to authenticated using (user_id=auth.uid()) with check (user_id=auth.uid()); create policy notification_events_authenticated_read on public.notification_events for select to authenticated using (true); create or replace function public.publish_location_notification(p_event_type text,p_location_id uuid,p_payload jsonb default '{}'::jsonb,p_dedupe_key text default null,p_expires_at timestamptz default null) returns uuid language plpgsql security invoker set search_path=public as $$ declare v_id uuid; begin insert into public.notification_events(event_type,actor_user_id,location_id,audience_scope,payload,dedupe_key,expires_at) values(p_event_type,auth.uid(),p_location_id,'nearby',coalesce(p_payload,'{}'::jsonb),p_dedupe_key,p_expires_at) on conflict (dedupe_key) where dedupe_key is not null do update set payload=excluded.payload,created_at=now(),expires_at=excluded.expires_at returning id into v_id; return v_id; end; $$;
